//! Seat labels from the baked glyph atlas (`docs/04-renderer.md` §12).
//!
//! The atlas is a multi-channel signed distance field of digits, capitals and
//! the punctuation of seat labels (`glyphs`, generated by
//! `tools/glyph-atlas/bake.py`). Its pixels arrive from the host with
//! `SetGlyphAtlas`; its metrics are compiled in.
//!
//! A seat's label is one instance of the `glyph` program ([`LABEL_STRIDE`]
//! bytes): its centre, its em size and up to [`MAX_GLYPHS`] glyphs. The ink
//! is not in it: the program reads the seat's category and visual state from
//! the seats' dynamic buffer, bound beside the label buffer at the seat's
//! `idx`, and looks the ink up in the palette. So a hold, a delta or a theme
//! change recolours labels without touching their buffers.
//!
//! Label buffers are built per render chunk on first need and kept in an LRU
//! of [`LABEL_CHUNKS`] chunks, all slots of one GPU buffer.

use std::ops::Range;

use cavea_format::full_label::seat_label;

use crate::{
    backend::{BackendError, BufferDesc, BufferId, BufferKind, BufferUsage, GpuBackend},
    scene::Scene,
};

pub mod atlas;
mod glyphs;
pub use glyphs::{ATLAS_SIZE, CAP_HEIGHT_EM, GLYPHS, RANGE_EM};

/// One glyph of the atlas.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Glyph {
    /// The ASCII character.
    pub ch: u8,
    /// Advance in em.
    pub advance: f32,
    /// Left, top, right, bottom in em from the pen position on the baseline,
    /// y down. All zero for the space.
    pub plane: [f32; 4],
    /// Left, top, right, bottom in atlas pixels.
    pub atlas: [f32; 4],
}

/// Glyph slots in a label instance; longer labels are not drawn (they could
/// not fit inside a seat at a legible size).
pub const MAX_GLYPHS: usize = 4;
/// Glyphs the `glyph` program's metrics block holds (`shaders/glyph.wgsl`).
pub const FONT_BLOCK_GLYPHS: usize = 64;
const _: () = assert!(GLYPHS.len() <= FONT_BLOCK_GLYPHS);

/// Bytes per label instance: centre `f32` × 2, em `f32` (chart units), glyph
/// codes `u8` × 4 (index in [`GLYPHS`] plus one; 0 is an empty slot), pen
/// positions `i8` × 4 (the glyph's origin from the label's centre, in 1/64
/// em).
pub const LABEL_STRIDE: usize = 20;
/// Render chunks whose label buffers are kept (04 §12, §22).
pub const LABEL_CHUNKS: usize = 64;
/// Chunks built in one frame at most: two of 4,096 seats take about 0.6 ms
/// (measured locally, release build). The others are built in the next
/// frames, which the engine asks for.
pub const LABEL_BUILDS_PER_FRAME: usize = 2;
/// Pen positions are stored in this fraction of an em.
const PEN_UNITS_PER_EM: f32 = 64.0;

/// The label's bounding box diagonal as a fraction of the seat's size: the
/// label fits inside a circle that size, with a margin.
pub const LABEL_FIT: f32 = 0.8;
/// Labels smaller than this em, in CSS pixels, are not drawn: the capitals
/// would be under 5 px tall. Compared on screen by the `glyph` program.
pub const LABEL_MIN_EM_PX: f32 = 7.0;

/// The width every glyph count is sized for, in em: tabular digits, so all
/// labels with as many digits as one another are the same size.
const NOMINAL_ADVANCE_EM: f32 = 0.5;

/// The em size, in chart units, of a label `width_em` wide with `glyphs`
/// glyphs on a seat `seat_cu` across (04 §12): the largest that fits its box
/// (width by capital height) inside [`LABEL_FIT`] of the seat. Labels of one
/// and two glyphs are sized alike, and every label at least as wide as that
/// many digits, so the numbers of a row look the same size.
pub fn label_em(seat_cu: f32, glyphs: usize, width_em: f32) -> f32 {
    let nominal = NOMINAL_ADVANCE_EM * glyphs.max(2) as f32;
    let width = width_em.max(nominal);
    seat_cu * LABEL_FIT / (width * width + CAP_HEIGHT_EM * CAP_HEIGHT_EM).sqrt()
}

/// The code of `c` in a label instance: its index in [`GLYPHS`] plus one.
/// `None` for anything the atlas does not hold.
pub fn glyph_code(c: char) -> Option<u8> {
    let byte = u8::try_from(c).ok()?;
    let i = GLYPHS.binary_search_by_key(&byte, |g| g.ch).ok()?;
    u8::try_from(i + 1).ok()
}

/// The glyph codes of `label`, their pen positions from its start in em, its
/// glyph count and its width in em. `None` when the label is empty, longer
/// than [`MAX_GLYPHS`], or has a character the atlas does not hold: such a
/// label is drawn from the dynamic atlas instead (04 §12), never in part.
pub fn layout(label: &str) -> Option<([u8; MAX_GLYPHS], [f32; MAX_GLYPHS], usize, f32)> {
    let mut codes = [0u8; MAX_GLYPHS];
    let mut origins = [0f32; MAX_GLYPHS];
    let mut n = 0;
    let mut width = 0.0;
    for c in label.chars() {
        let code = glyph_code(c)?;
        let glyph = GLYPHS.get(usize::from(code) - 1)?;
        *codes.get_mut(n)? = code;
        *origins.get_mut(n)? = width;
        width += glyph.advance;
        n += 1;
    }
    (n > 0).then_some((codes, origins, n, width))
}

/// One label instance for `label` centred at `pos` on a seat `seat_cu`
/// across ([`layout`] says which labels have none).
pub fn label_instance(label: &str, pos: [f32; 2], seat_cu: f32) -> Option<[u8; LABEL_STRIDE]> {
    let (codes, origins, n, width) = layout(label)?;
    let mut out = [0; LABEL_STRIDE];
    let em = label_em(seat_cu, n, width);
    let fields = pos.into_iter().chain([em]).flat_map(f32::to_le_bytes);
    for (slot, byte) in out.iter_mut().zip(fields) {
        *slot = byte;
    }
    let (_, glyphs) = out.split_at_mut(12);
    let (code_bytes, pen_bytes) = glyphs.split_at_mut(MAX_GLYPHS);
    code_bytes.copy_from_slice(&codes);
    for (byte, &origin) in pen_bytes.iter_mut().zip(&origins).take(n) {
        // Within ±(4 × the widest advance) / 2 em, so well inside i8.
        *byte = (((origin - width / 2.0) * PEN_UNITS_PER_EM).round() as i8) as u8;
    }
    Some(out)
}

/// The `glyph` program's constant metrics block, std140: the distance range
/// and capital height in em and the atlas size in pixels, then the plane
/// bounds of [`FONT_BLOCK_GLYPHS`] glyphs, then their atlas bounds. The GL
/// backend uploads it once.
pub fn font_block() -> Vec<u8> {
    let mut out = Vec::with_capacity(16 * (1 + 2 * FONT_BLOCK_GLYPHS));
    let [w, h] = ATLAS_SIZE.map(|v| v as f32);
    let mut push = |v: [f32; 4]| {
        v.iter()
            .for_each(|f| out.extend_from_slice(&f.to_le_bytes()))
    };
    push([RANGE_EM, CAP_HEIGHT_EM, w, h]);
    for field in [|g: &Glyph| g.plane, |g: &Glyph| g.atlas] {
        for i in 0..FONT_BLOCK_GLYPHS {
            push(GLYPHS.get(i).map_or([0.0; 4], field));
        }
    }
    out
}

/// The label buffers of a loaded chart: one GPU buffer of up to
/// [`LABEL_CHUNKS`] slots, each the size of the chart's largest render chunk.
#[derive(Default)]
pub struct Labels {
    /// Created on first need.
    buffer: Option<BufferId>,
    /// Seats per slot.
    slot_seats: usize,
    /// Per slot: the chunk it holds and when it was last drawn.
    slots: Vec<(u32, u64)>,
    /// Per render chunk: its slot, if it has one.
    slot_of: Vec<Option<u8>>,
    clock: u64,
    /// Per slot: its seats whose label the baked atlas cannot draw, for the
    /// dynamic atlas.
    skipped: Vec<Vec<u32>>,
    /// Instance bytes being built, kept so building allocates once.
    scratch: Vec<u8>,
    /// Chunks built since load, for the demo's readout and tests.
    pub built: u32,
}

impl Labels {
    /// The GPU buffer, to destroy with the chart.
    pub fn buffer(&self) -> Option<BufferId> {
        self.buffer
    }

    /// Seats of chunk `c` whose labels the baked atlas cannot draw, if its
    /// labels are built.
    pub fn skipped(&self, c: u32) -> &[u32] {
        let slot = self.slot_of.get(c as usize).copied().flatten();
        let skipped = slot.and_then(|s| self.skipped.get(usize::from(s)));
        skipped.map_or(&[], Vec::as_slice)
    }

    /// Chunks with a label buffer.
    pub fn len(&self) -> usize {
        self.slots.len()
    }

    pub fn is_empty(&self) -> bool {
        self.slots.is_empty()
    }

    /// Makes sure each chunk of `visible` has its label buffer, building those
    /// that do not (evicting the least recently drawn when all slots are
    /// taken), and writes their draw ranges: the seats of each within
    /// `active`, with the instance in the label buffer where the range starts.
    /// At most [`LABEL_CHUNKS`] chunks get labels in one frame, and at most
    /// [`LABEL_BUILDS_PER_FRAME`] are built: returns whether any visible chunk
    /// is still waiting for its buffer. Allocates nothing once the scratch
    /// buffer has grown to a chunk.
    pub fn prepare(
        &mut self,
        backend: &mut impl GpuBackend,
        scene: &Scene,
        visible: &[u32],
        ranges: &mut Vec<Range<u32>>,
        bases: &mut Vec<u32>,
    ) -> Result<bool, BackendError> {
        ranges.clear();
        bases.clear();
        let chunks = &scene.chart.chunks;
        if self.buffer.is_none() {
            self.slot_seats = chunks
                .iter()
                .map(|c| c.seat_count as usize)
                .max()
                .unwrap_or(0);
            let slots = chunks.len().min(LABEL_CHUNKS);
            let desc = BufferDesc {
                kind: BufferKind::Vertex,
                usage: BufferUsage::Dynamic,
            };
            let zeros = vec![0; slots * self.slot_seats * LABEL_STRIDE];
            self.buffer = Some(backend.create_buffer(desc, &zeros)?);
            self.slot_of = vec![None; chunks.len()];
        }
        let Some(buffer) = self.buffer else {
            return Ok(false);
        };
        self.clock += 1;
        let (mut builds, mut waiting) = (0, false);
        for &c in visible.iter().take(LABEL_CHUNKS) {
            let Some(chunk) = chunks.get(c as usize) else {
                continue;
            };
            let slot = match self.slot_of.get(c as usize).copied().flatten() {
                Some(slot) => slot,
                None if builds == LABEL_BUILDS_PER_FRAME => {
                    waiting = true;
                    continue;
                }
                None => {
                    builds += 1;
                    let slot = self.claim(c)?;
                    self.build(backend, buffer, scene, c, slot)?;
                    slot
                }
            };
            if let Some(entry) = self.slots.get_mut(usize::from(slot)) {
                entry.1 = self.clock;
            }
            let first = chunk.seat_first;
            let end = first.saturating_add(chunk.seat_count);
            let seats = first.max(scene.active.start)..end.min(scene.active.end);
            if !seats.is_empty() {
                let base = usize::from(slot) * self.slot_seats + (seats.start - first) as usize;
                bases.push(u32::try_from(base).map_err(|_| BackendError::InvalidData)?);
                ranges.push(seats);
            }
        }
        Ok(waiting)
    }

    /// A slot for chunk `c`: a free one, or the least recently drawn one not
    /// drawn in this frame.
    fn claim(&mut self, c: u32) -> Result<u8, BackendError> {
        let free = self.slots.len();
        let slot = if free < LABEL_CHUNKS.min(self.slot_of.len()) {
            self.slots.push((c, 0));
            self.skipped.push(Vec::new());
            free
        } else {
            let lru = (0..self.slots.len())
                .filter(|&i| self.slots.get(i).is_some_and(|s| s.1 != self.clock))
                .min_by_key(|&i| self.slots.get(i).map_or(0, |s| s.1))
                .ok_or(BackendError::InvalidData)?;
            if let Some(entry) = self.slots.get_mut(lru) {
                if let Some(old) = self.slot_of.get_mut(entry.0 as usize) {
                    *old = None;
                }
                *entry = (c, 0);
            }
            lru
        };
        let slot = u8::try_from(slot).map_err(|_| BackendError::InvalidData)?;
        if let Some(entry) = self.slot_of.get_mut(c as usize) {
            *entry = Some(slot);
        }
        Ok(slot)
    }

    /// Writes chunk `c`'s label instances into `slot`.
    fn build(
        &mut self,
        backend: &mut impl GpuBackend,
        buffer: BufferId,
        scene: &Scene,
        c: u32,
        slot: u8,
    ) -> Result<(), BackendError> {
        let chart = &scene.chart;
        let chunk = chart
            .chunks
            .get(c as usize)
            .ok_or(BackendError::InvalidData)?;
        self.scratch.clear();
        let skipped = self
            .skipped
            .get_mut(usize::from(slot))
            .ok_or(BackendError::InvalidData)?;
        skipped.clear();
        for idx in chunk.seat_first..chunk.seat_first.saturating_add(chunk.seat_count) {
            let seat_cu = scene
                .row
                .get(idx as usize)
                .and_then(|&r| chart.rows.get(r as usize))
                .map_or(scene.seat_size, |r| f32::from(r.seat_size) * 0.25);
            let pos = scene.pos.get(idx as usize).copied().unwrap_or_default();
            let label = seat_label(chart, idx).ok();
            let instance = label.and_then(|label| {
                let instance = label_instance(label.seat.as_str(), pos, seat_cu);
                if instance.is_none() && !label.seat.as_str().is_empty() {
                    skipped.push(idx);
                }
                instance
            });
            self.scratch
                .extend_from_slice(&instance.unwrap_or_default());
        }
        let offset = usize::from(slot) * self.slot_seats * LABEL_STRIDE;
        let offset = u32::try_from(offset).map_err(|_| BackendError::InvalidData)?;
        backend.update_buffer(buffer, offset, &self.scratch)?;
        self.built += 1;
        Ok(())
    }
}

#[cfg(test)]
impl Labels {
    /// Chunk `c`'s slot, if it has one.
    pub fn slot(&self, c: usize) -> Option<u8> {
        self.slot_of.get(c).copied().flatten()
    }

    /// Builds chunk `c` into slot 0 again, to time it.
    pub fn rebuild_for_measurement(
        &mut self,
        backend: &mut impl GpuBackend,
        scene: &Scene,
        c: u32,
    ) -> Result<(), BackendError> {
        let buffer = self.buffer.ok_or(BackendError::UnknownResource)?;
        self.build(backend, buffer, scene, c, 0)
    }
}

